import sys, json, random, time
from array import array
sys.path.insert(0, "/workspace/tests")
from run_sub import run

def signature(r):
    return (r['rcode'], frozenset((x['owner'],x['type'],x['data']) for x in r['answer']))

def brute(doc, out):
    matrix = {(r['query'],r['profile']): signature(r) for r in out['runs']}
    costs = {q['id']:q['cost'] for q in doc['queries']}
    qids = sorted(costs); pids = sorted(p['id'] for p in doc['profiles'])
    pairs = []
    for i,p1 in enumerate(pids):
        for p2 in pids[i+1:]:
            if any(matrix[(q,p1)] != matrix[(q,p2)] for q in qids):
                pairs.append((p1,p2))
    if not pairs: return (0,0)
    masks = []
    for q in qids:
        m = 0
        for i,(p1,p2) in enumerate(pairs):
            if matrix[(q,p1)] != matrix[(q,p2)]: m |= 1<<i
        masks.append((m, costs[q]))
    full = (1<<len(pairs))-1
    n = len(masks); size = 1<<n
    unions = array('I', bytes(4*size)); costs_arr = array('H', bytes(2*size))
    best = None
    for m in range(size):
        if m:
            low = m & -m; i = low.bit_length()-1; prev = m ^ low
            u = unions[prev] | masks[i][0]; unions[m] = u
            c = costs_arr[prev] + masks[i][1]; costs_arr[m] = c
        else:
            u = 0; c = 0
        if u == full:
            key = (c, m.bit_count())
            if best is None or key < best: best = key
    return best

random.seed(99)
names = ["a.t.","b.t.","c.t.","x.y.t.","t.","*.t.","d.e.t."]
types = ["A","AAAA","TXT","CNAME"]
worst = 0
for trial in range(40):
    zrecs = []
    for _ in range(random.randint(0,7)):
        owner = random.choice(names); ty = random.choice(types)
        if ty == "A": data = "%d.%d.%d.%d" % tuple(random.randint(0,255) for _ in range(4))
        elif ty == "AAAA": data = "2001:db8::%d" % random.randint(0,9)
        elif ty == "TXT": data = "t%d" % random.randint(0,99)
        else: data = random.choice(names)
        zrecs.append({"owner":owner,"type":ty,"data":data})
    byowner = {}
    for r in zrecs:
        byowner.setdefault(r["owner"], {}).setdefault(r["type"], set()).add(r["data"])
    bad = False
    for o, ts in byowner.items():
        if "CNAME" in ts and (len(ts) > 1 or len(ts["CNAME"]) > 1 or o == "t."): bad = True
    if bad: continue
    profiles = [{"id":"p%d"%i,"max_aliases":random.randint(0,3),
                 "cname":random.choice(["follow","stop"]),
                 "wildcard":random.choice(["rfc","off","one-label"])} for i in range(random.randint(2,8))]
    queries = [{"id":"q%02d"%i,"name":random.choice(names),
                "type":random.choice(types),"cost":random.randint(1,1000)} for i in range(random.randint(1,20))]
    doc = {"zones":[{"origin":"t.","records":zrecs}],"profiles":profiles,
           "queries":queries,"observations":[]}
    t0=time.time()
    out = run(doc)
    dt = time.time()-t0
    worst = max(worst, dt)
    assert 'error' not in out, out
    d = out['diagnostic']
    b = brute(doc, out)
    assert (d['cost'], d['count']) == b, (trial, d, b, len(profiles), len(queries))
    assert d['basis'] == sorted(d['basis'])
print("stress OK; worst runtime %.2fs" % worst)

